import{_ as i,o as t,c as r,ah as a}from"./chunks/framework.Bja9t6Wf.js";const m=JSON.parse('{"title":"Das Konzept: Das Horten-Mysterium","description":"","frontmatter":{},"headers":[],"relativePath":"konzept.md","filePath":"konzept.md"}'),n={name:"konzept.md"};function s(d,e,h,o,u,l){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="das-konzept-das-horten-mysterium" tabindex="-1">Das Konzept: Das Horten-Mysterium <a class="header-anchor" href="#das-konzept-das-horten-mysterium" aria-label="Permalink to &quot;Das Konzept: Das Horten-Mysterium&quot;">​</a></h1><p><strong>Arbeitstitel:</strong> <em>Das Horten-Mysterium: Eine fabelhafte Fiktion von Macht, Geld und Perlen</em></p><h2 id="die-vision" tabindex="-1">Die Vision <a class="header-anchor" href="#die-vision" aria-label="Permalink to &quot;Die Vision&quot;">​</a></h2><p>Diese Mockumentary ist eine satirische und zugleich tiefgründige Auseinandersetzung mit dem Erbe eines der reichsten und umstrittensten Paare der deutsch-österreichischen Geschichte: Heidi und Helmut Horten.</p><p>Wir verbinden historische Fakten mit fiktiven Elementen, um die Absurdität von extremem Reichtum, die Mechanismen der Verdrängung und die Verflechtungen zwischen Kapital und Politik aufzuzeigen.</p><h2 id="die-struktur-4-teile" tabindex="-1">Die Struktur (4 Teile) <a class="header-anchor" href="#die-struktur-4-teile" aria-label="Permalink to &quot;Die Struktur (4 Teile)&quot;">​</a></h2><h3 id="_1-die-schillernde-witwe" tabindex="-1">1. Die schillernde Witwe <a class="header-anchor" href="#_1-die-schillernde-witwe" aria-label="Permalink to &quot;1. Die schillernde Witwe&quot;">​</a></h3><p>Ein Blick auf Heidis Leben nach dem Tod ihres Mannes. Wir zeigen ihren exzentrischen Luxus, ihre Kunstsammlung und ihre Rolle als &quot;Grande Dame&quot; der Gesellschaft.</p><h3 id="_2-der-aufstieg-des-helmut-horten" tabindex="-1">2. Der Aufstieg des Helmut Horten <a class="header-anchor" href="#_2-der-aufstieg-des-helmut-horten" aria-label="Permalink to &quot;2. Der Aufstieg des Helmut Horten&quot;">​</a></h3><p>Wir dokumentieren Helmuts Weg zum Kaufhaus-König. Der Fokus liegt hierbei auf der &quot;Marktbereinigung&quot; der 1930er Jahre.</p><h3 id="_3-das-schicksal-der-verlierer" tabindex="-1">3. Das Schicksal der Verlierer <a class="header-anchor" href="#_3-das-schicksal-der-verlierer" aria-label="Permalink to &quot;3. Das Schicksal der Verlierer&quot;">​</a></h3><p>Was geschah mit denen, die ihre Kaufhäuser abgeben mussten? Wir beleuchten das Schicksal der Gebrüder Alsberg.</p><h3 id="_4-die-politische-liebesgeschichte" tabindex="-1">4. Die politische Liebesgeschichte <a class="header-anchor" href="#_4-die-politische-liebesgeschichte" aria-label="Permalink to &quot;4. Die politische Liebesgeschichte&quot;">​</a></h3><p>Die Beziehung zur ÖVP. Wir widmen uns dem &quot;Regen aus Gold&quot; – den Spenden und der Stückelung.</p><hr><p><em>Dieses Projekt ist eine Gratwanderung zwischen Dokumentation und Satire.</em></p>',16)])])}const p=i(n,[["render",s]]);export{m as __pageData,p as default};
